import sys
from itertools import permutations
from bisect import bisect_left

def lis(seq):
    t = []
    for x in seq:
        i = bisect_left(t, x)
        if i == len(t): t.append(x)
        else: t[i] = x
    return len(t)

def main():
    A, B, M = map(int, sys.stdin.read().split())
    N = A * B - 1
    cnt = 0
    for p in permutations(range(1, N + 1)):
        if lis(p) != A:
            continue
        if lis([-x for x in p]) != B:
            continue
        ok = False
        for n in range(0, N + 1):
            small = [x for x in p if x <= n]
            large = [x for x in p if x > n]
            if lis(small) <= A - 1 and lis([-x for x in large]) <= B - 1:
                ok = True
                break
        if ok:
            cnt += 1
    print(cnt % M)

main()

