import sys, heapq
def main():
    data=sys.stdin.buffer.read().split()
    t=int(data[0]); pos=1; out=[]
    for _ in range(t):
        n=int(data[pos]); m=int(data[pos+1]); pos+=2
        boxes=[]
        for i in range(n):
            boxes.append((int(data[pos]),int(data[pos+1]))); pos+=2
        boxes.sort(key=lambda x:-x[0])
        K=m-1
        suf=[0]*(n+1)
        for i in range(n-1,-1,-1):
            v,p=boxes[i]
            d=v-p
            suf[i]=suf[i+1]+(d if d>0 else 0)
        best=0
        heap=[]; sumP=0
        for p in range(0,n+1):
            if p>0 and K>0:
                P=boxes[p-1][1]
                if len(heap)<K:
                    heapq.heappush(heap,-P); sumP+=P
                else:
                    if P<-heap[0]:
                        top=-heapq.heapreplace(heap,-P)
                        sumP+=P-top
            if len(heap)==K:
                cand=(K-sumP)+suf[p]
                if cand>best: best=cand
        out.append(str(best))
    print("\n".join(out))
main()

