def solve(V,P,M,D):
    N=len(V)
    @lru_cache(None)
    def val(state,d):
        if d==0: return 0
        best=None
        for t in range(M):
            opts=[0]
            for idx,(tt,r) in enumerate(state):
                if tt==t and r>0:
                    ns=list(state); ns[idx]=(tt,r-1)
                    opts.append(1+val(tuple(sorted(ns)),d-1))
