class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        L = len(s)
        g = [0] * (L + 2)
        def pc(x):
            return bin(x).count('1')
        for c in range(2, L + 2):
            g[c] = 1 + g[pc(c)]
        N = L + 1
        C = [[0] * (N + 1) for _ in range(N + 1)]
        for i in range(N + 1):
            C[i][0] = 1
            for j in range(1, i + 1):
                C[i][j] = (C[i-1][j-1] + C[i-1][j]) % MOD
        cnt = [0] * (L + 1)
        ones = 0
        for i, ch in enumerate(s):
            rem = L - i - 1
            if ch == '1':
                for c in range(ones, L + 1):
                    need = c - ones
                    if need <= rem:
                        cnt[c] += C[rem][need]
                ones += 1
        ans = 0
        for c in range(1, L + 1):
            if g[c] <= k - 1:
                ans += cnt[c]
        return ans % MOD

