                for c in range(ones, L + 1):
                    need = c - ones
                    if need <= rem:
                        cnt[c] += C[rem][need]
                ones += 1
        ans = 0
        for c in range(1, L + 1):
            if g[c] <= k - 1:
                ans += cnt[c]
        return ans % MOD

