    if x == 0:
        return 0
    while x % 2 == 0:
        x //= 2
    return 1 if x % 4 == 1 else 0

def solve(A, D):
    INF = 10**9
    memo = {}
    def F(key, depth, flag):
        if depth == 0:
            if not flag:
                return INF
            tot = 0
            for (v, t, c) in key:
                if t == 0:
                    tot += c * s(v)
                else:
                    tot += c * (1 if v % 2 == 0 else 0)
            return tot
        if not key and flag:
            return 0
        mk = (key, depth, flag)
        if mk in memo:
            return memo[mk]
        best = INF
        for d in (0, 1):
            const = 0
            new = {}
            for (v, t, c) in key:
                if t == 1:
                    if (d + v) % 2 == 0:
                        const += c
                else:
                    nv = (v + d) >> 1
                    nt = 0 if (v + d) % 2 == 0 else 1
                    new[(nv, nt)] = new.get((nv, nt), 0) + c
            nk = tuple(sorted((v, t, c) for (v, t), c in new.items()))
            r = F(nk, depth - 1, flag or d == 1)
            if r < INF:
                best = min(best, const + r)
        memo[mk] = best
        return best
    init = {}
    for a in A:
        init[(a, 0)] = init.get((a, 0), 0) + 1
    key = tuple(sorted((v, t, c) for (v, t), c in init.items()))
    return len(A) - F(key, D, False)

