def main():
    d=sys.stdin.read().split()
    n,m=int(d[0]),int(d[1])
    adj=[0]*n
    for i in range(m):
        u=int(d[2+2*i])-1; v=int(d[3+2*i])-1
        adj[u]|=1<<v; adj[v]|=1<<u
    rows=adj[:]
    piv=[]
    r=0
    for c in range(n):
        sel=-1
        for i in range(r,n):
            if rows[i]>>c&1:
                sel=i;break
        if sel<0: continue
        rows[r],rows[sel]=rows[sel],rows[r]
        for i in range(n):
            if i!=r and rows[i]>>c&1:
                rows[i]^=rows[r]
        piv.append((r,c))
        r+=1
    pivcols={c for _,c in piv}
    X=[0]*n
    k=0
    for f in range(n):
        if f in pivcols: continue
        vec=1<<f
        for (ri,p) in piv:
            if rows[ri]>>f&1:
                vec|=1<<p
        for v in range(n):
            if vec>>v&1:
                X[v]|=1<<k
        k+=1
    if any(x==0 for x in X):
        print("No")
    else:
        print("Yes")
        print(*X)
