from typing import List
class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n = len(grid); m = len(grid[0])
        dirs = [(1,1),(1,-1),(-1,-1),(-1,1)]  # clockwise order
        def req(v):
            return 0 if v == 2 else 2
        A = []
        for k in range(4):
            dr, dc = dirs[k]
            Ak = [[1]*m for _ in range(n)]
            rows = range(n-1, -1, -1) if dr == 1 else range(n)
            for i in rows:
                gi = grid[i]
                for j in range(m):
                    ni = i + dr; nj = j + dc
                    if 0 <= ni < n and 0 <= nj < m and grid[ni][nj] == req(gi[j]):
                        Ak[i][j] = 1 + Ak[ni][nj]
            A.append(Ak)
        best = 0
        for k in range(4):
            dr, dc = dirs[k]
            Bk = [[1]*m for _ in range(n)]
            Ac = A[(k+1) % 4]
            rows = range(n-1, -1, -1) if dr == 1 else range(n)
            for i in rows:
                gi = grid[i]
                for j in range(m):
                    ni = i + dr; nj = j + dc
                    if 0 <= ni < n and 0 <= nj < m and grid[ni][nj] == req(gi[j]):
                        Bk[i][j] = 1 + max(Bk[ni][nj], Ac[ni][nj])
                    if gi[j] == 1 and Bk[i][j] > best:
                        best = Bk[i][j]
        return best

