from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        def cnt(o, e, p):
            if o + e == 0:
                return 1
            if p == 1:
                ok = (o == e or o == e + 1)
            else:
                ok = (e == o or e == o + 1)
            return factorial(o) * factorial(e) if ok else 0

        rem = list(range(1, n + 1))
        res = []
        last = None
        for _ in range(n):
            chosen = False
            for idx, x in enumerate(rem):
                px = x & 1
                if last is not None and px == (last & 1):
                    continue
                left = rem[:idx] + rem[idx + 1:]
                o = sum(1 for v in left if v & 1)
                e = len(left) - o
                c = cnt(o, e, 1 - px)
                if k <= c:
                    res.append(x)
                    rem = left
                    last = x
                    chosen = True
                    break
                k -= c
            if not chosen:
                return []
        return res

