def solve(n,A,B,C):
    S0=sum(C[i] for i in range(n) if A[i])
    P=[C[i] for i in range(n) if A[i]==1 and B[i]==0]
    Q=[C[i] for i in range(n) if A[i]==0 and B[i]==1]
    M1=sorted([C[i] for i in range(n) if A[i]==1 and B[i]==1],reverse=True)
    vals=sorted(set(C)); L=len(vals)
    rank={v:i+1 for i,v in enumerate(vals)}
    class F:
        def __init__(s):
            s.c=[0]*(L+1); s.s=[0]*(L+1); s.tot=0
        def add(s,x):
            i=rank[x]; s.tot+=1
            while i<=L:
                s.c[i]+=1; s.s[i]+=x; i+=i&-i
        def query(s,x):
            i=rank[x]; cl=0; sl=0; j=i
            while j>0:
                cl+=s.c[j]; sl+=s.s[j]; j-=j&-j
            return sl + x*(s.tot-cl)
    fn=F(); fp=F(); PMN=0; PMP=0
    for x in P:
        PMN+=fn.query(x); fn.add(x)
    for x in Q:
        PMP+=fp.query(x); fp.add(x)
