class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        h = (n + 1) // 2
        pw = [1 % k] * n
        for i in range(1, n):
            pw[i] = pw[i - 1] * 10 % k
        w = [0] * h
        for i in range(h):
            j = n - 1 - i
            if i == j:
                w[i] = pw[i]
            else:
                w[i] = (pw[i] + pw[j]) % k
        full = (1 << k) - 1

        def rot(m, r):
            if r == 0:
                return m
            return ((m << r) | (m >> (k - r))) & full

        reach = [0] * (h + 1)
        reach[h] = 1
        for i in range(h - 1, -1, -1):
            lo = 1 if i == 0 else 0
            m = 0
            for d in range(lo, 10):
                m |= rot(reach[i + 1], (d * w[i]) % k)
            reach[i] = m
        digits = []
        r = 0
        for i in range(h):
            lo = 1 if i == 0 else 0
            chosen = None
            for d in range(9, lo - 1, -1):
                s = (r + d * w[i]) % k
                need = (-s) % k
                if (reach[i + 1] >> need) & 1:
                    chosen = d
                    r = s
                    break
            digits.append(chosen)
        half = digits
        if n % 2 == 0:
            rest = half[::-1]
        else:
            rest = half[:-1][::-1]
        return ''.join(map(str, half + rest))

