from typing import List
class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        a = nums
        nxt = [n] * (n + 1)
        stack = []
        for i in range(n - 1, -1, -1):
            while stack and a[stack[-1]] <= a[i]:
                stack.pop()
            nxt[i] = stack[-1] if stack else n
            stack.append(i)
        G = [0] * (n + 1)
        for i in range(n - 1, -1, -1):
            G[i] = a[i] * (nxt[i] - i) + G[nxt[i]]
        LOG = 18
        up = [nxt]
        for j in range(1, LOG):
            prev = up[-1]
            up.append([prev[prev[i]] for i in range(n + 1)])
        P = [0] * (n + 1)
        for i in range(n):
            P[i + 1] = P[i] + a[i]
        upr = up[::-1]

        def cost(l, r):
            p = l
            for tbl in upr:
                q = tbl[p]
                if q <= r:
                    p = q
            S = G[l] - G[p] + a[p] * (r - p + 1)
            return S - (P[r + 1] - P[l])

        ans = 0
        r = 0
        for l in range(n):
            if r < l:
                r = l
            while r + 1 < n and cost(l, r + 1) <= k:
                r += 1
            ans += r - l + 1
        return ans

