def omega(N,K,n):
    M=N-K+1
    O=[[F(0)]*N for _ in range(N)]
    for x in range(N):
        for y in range(N):
            O[x][y]=F(1,2) if x<y else (F(-1,2) if x>y else F(0))
    for _ in range(n):
        new=[[F(0)]*N for _ in range(N)]
        for i in range(M):
            W=set(range(i,i+K))
            A=[row[:] for row in O]
            for a in range(N):
                if a in W: continue
                for r in W:
                    A[a][r]=sum(O[a][b] for b in W)/K
                    A[r][a]=-A[a][r]
            for r in W:
                for s in W: A[r][s]=F(0)
            for a in range(N):
                for b in range(N): new[a][b]+=A[a][b]/M
        O=new
    return O
