import bisect

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        k1 = p.index('*'); k2 = p.index('*', k1+1)
        a, b, c = p[:k1], p[k1+1:k2], p[k2+1:]
        def occ(x, t):
            m = len(x); n = len(t)
            if m == 0:
                return list(range(n+1))
            f = [0]*m; k = 0
            for i in range(1, m):
                while k and x[i] != x[k]:
                    k = f[k-1]
                if x[i] == x[k]:
                    k += 1
                f[i] = k
            res = []; k = 0
            for i, ch in enumerate(t):
                while k and ch != x[k]:
                    k = f[k-1]
                if ch == x[k]:
                    k += 1
                if k == m:
                    res.append(i-m+1)
                    k = f[k-1]
            return res
        A = occ(a, s); B = occ(b, s); C = occ(c, s)
        la, lb, lc = len(a), len(b), len(c)
        best = -1
        for q in B:
            idx = bisect.bisect_right(A, q-la) - 1
            if idx < 0:
                continue
            i = A[idx]
            idx2 = bisect.bisect_left(C, q+lb)
            if idx2 >= len(C):
                continue
            j = C[idx2]
            L = j+lc-i
            if best < 0 or L < best:
                best = L
        return best

