import sys
def main():
    data=sys.stdin.buffer.read().split()
    n=int(data[0]); m=int(data[1])
    parent=list(range(n+1)); w=[0]*(n+1); sz=[1]*(n+1)
    def find(x):
        path=[]
        while parent[x]!=x:
            path.append(x); x=parent[x]
        root=x
        acc=0
        for node in reversed(path):
            acc^=w[node]; w[node]=acc; parent[node]=root
        return root
    idx=2
    for _ in range(m):
        x=int(data[idx]); y=int(data[idx+1]); z=int(data[idx+2]); idx+=3
        rx=find(x); ry=find(y)
        px=w[x] if x!=rx else 0
        py=w[y] if y!=ry else 0
        if rx==ry:
            if px^py!=z:
                print(-1); return
        else:
            if sz[rx]>sz[ry]:
                rx,ry=ry,rx
            parent[rx]=ry
            w[rx]=px^py^z
            sz[ry]+=sz[rx]
    groups={}
    pot=[0]*(n+1); root=[0]*(n+1)
    for v in range(1,n+1):
        r=find(v)
        root[v]=r
        pot[v]=w[v] if v!=r else 0
        if r in groups: groups[r].append(v)
        else: groups[r]=[v]
    rval={}
    for r,mem in groups.items():
        size=len(mem)
        val=0
        for b in range(31):
            c1=0
            for v in mem:
                c1+=(pot[v]>>b)&1
            if 2*c1>size:
                val|=1<<b
        rval[r]=val
    out=[pot[v]^rval[root[v]] for v in range(1,n+1)]
    print(' '.join(map(str,out)))
