import itertools, numpy as np
def brute(N,M):
    def nbrs(pos):
        if pos==(-1,0): return [(r,1) for r in range(N)]
        r,d=pos
        res=[(-1,0) if d==1 else (r,d-1)]
        if d<M: res.append((r,d+1))
        return res
    idx={}
    for ks in itertools.product(range(M+1),repeat=N):
        for p in [(-1,0)]+[(r,d) for r in range(N) for d in range(1,M+1)]:
            if p!=(-1,0) and p[1]>ks[p[0]]: continue
            idx[(ks,p)]=len(idx)
    n=len(idx)
    A=np.zeros((n,n)); b=np.zeros(n)
    for (ks,p),i in idx.items():
        A[i,i]=1
        if all(k==M for k in ks): continue
        nb=nbrs(p); w=1/len(nb)
        b[i]=1
        for q in nb:
            nk=list(ks)
            if q!=(-1,0) and q[1]>nk[q[0]]: nk[q[0]]=q[1]
            A[i,idx[(tuple(nk),q)]]-=w
    x=np.linalg.solve(A,b)
    return x[idx[((0,)*N,(-1,0))]]
