def solve_small(N, A, B):
    # exact BFS over occupancy bitmasks; each piece moves toward chosen square
    start = 0
    for i, ch in enumerate(A):
        if ch == '1':
            start |= 1 << i
    tgt = 0
    for i, ch in enumerate(B):
        if ch == '1':
            tgt |= 1 << i
    # represent configuration as tuple of counts for exactness
    cnt0 = tuple(1 if A[i] == '1' else 0 for i in range(N))
    tcnt = tgt
    dist = {cnt0: 0}
    q = deque([cnt0])
    while q:
        s = q.popleft()
        occ = 0
        for i in range(N):
            if s[i]:
                occ |= 1 << i
        if occ == tgt:
            return dist[s]
        for c in range(N):
            ns = [0] * N
            for j in range(N):
                if s[j]:
                    if c > j:
                        ns[j + 1] += s[j]
                    elif c < j:
                        ns[j - 1] += s[j]
                    else:
                        ns[j] += s[j]
            ns = tuple(ns)
            if ns not in dist:
                dist[ns] = dist[s] + 1
                q.append(ns)
    return -1

