import heapq
class Solution:
    def minOperations(self, n: int, m: int) -> int:
        def is_prime(x):
            if x < 2:
                return False
            i = 2
            while i * i <= x:
                if x % i == 0:
                    return False
                i += 1
            return True
        if is_prime(n) or is_prime(m):
            return -1
        L = len(str(n))
        def neighbors(v):
            s = str(v).zfill(L)
            res = []
            for i, ch in enumerate(s):
                d = int(ch)
                for nd in (d - 1, d + 1):
                    if 0 <= nd <= 9:
                        t = s[:i] + str(nd) + s[i+1:]
                        res.append(int(t))
            return res
        INF = float('inf')
        dist = {n: n}
        pq = [(n, n)]
        while pq:
            d, v = heapq.heappop(pq)
            if d != dist.get(v, INF):
                continue
            if v == m:
                return d
            for u in neighbors(v):
                if is_prime(u):
                    continue
                nd = d + u
                if nd < dist.get(u, INF):
                    dist[u] = nd
                    heapq.heappush(pq, (nd, u))
        return -1

