import numpy as np
class Solution:
    def beautifulSplits(self, nums):
        n = len(nums)
        if n < 3:
            return 0
        a = np.array(nums, dtype=np.int64)
        isA = [False]*n
        for i in range(1, n):
            if 2*i <= n-1 and nums[:i] == nums[i:2*i]:
                isA[i] = True
        A = 0
        for i in range(1, n):
            if isA[i]:
                A += n - 2*i
        B = 0
        AB = 0
        prev = np.zeros(n+1, dtype=np.int64)
        for i in range(n-1, 0, -1):
            cur = np.zeros(n+1, dtype=np.int64)
            if i+1 < n:
                cur[i+1:n] = np.where(a[i+1:n] == a[i], prev[i+2:n+1] + 1, 0)
                j = np.arange(i+1, n, dtype=np.int64)
                cond = (cur[i+1:n] >= j - i) & (2*j - i <= n)
                B += int(cond.sum())
                if isA[i]:
                    cond2 = cond & (j >= 2*i)
                    AB += int(cond2.sum())
            prev = cur
        return A + B - AB

