                j = np.arange(i+1, n, dtype=np.int64)
                cond = (cur[i+1:n] >= j - i) & (2*j - i <= n)
                B += int(cond.sum())
                if isA[i]:
                    cond2 = cond & (j >= 2*i)
                    AB += int(cond2.sum())
            prev = cur
        return A + B - AB

